          "code": "import pandas as pd\nimport numpy as np\nimport statsmodels.api as sm\n\ndef summary_report(arrays: list, random_seed: int = 0) -> dict:\n    \"\"\"\n    Generate Pandas DataFrames from multiple 2D lists and perform a multiple\n    linear regression on each, returning a summary report.\n\n    For each dataset the function validates the input list, creates a DataFrame,\n    separates independent and dependent variables, adds a constant to the model,\n    and fits a linear regression using statsmodels.\n\n    Parameters:\n    - arrays (list of 2D lists): Each 2D list is a dataset where every sub-list\n      (row) has exactly 5 elements: the first 4 are independent variables\n      ('A', 'B', 'C', 'D') and the last is the dependent ('Response') variable.\n    - random_seed (int): Seed for reproducibility in numpy for statsmodels. Defaults to 0.\n\n    Returns:\n    - dict with keys:\n        'DataFrames'           -> list of pd.DataFrame (columns A, B, C, D, Response)\n        'Regression_Results'   -> list of statsmodels RegressionResultsWrapper\n        'R_Squared_Comparison' -> dict mapping 'Dataset_1', 'Dataset_2', ... to each R-squared\n    \"\"\"\n    np.random.seed(random_seed)\n\n    if not isinstance(arrays, list) or not all(isinstance(a, list) for a in arrays):\n        raise ValueError(\"Input must be a list of 2D lists (list of list of lists).\")\n    if len(arrays) == 0:\n        raise ValueError(\"Input list must not be empty.\")\n\n    dataframes = []\n    results_list = []\n    r_squared_comparison = {}\n\n    for i, array in enumerate(arrays, start=1):\n        if not isinstance(array, list) or not all(isinstance(row, list) for row in array):\n            raise ValueError(f\"Dataset {i}: input must be a 2D list (list of lists).\")\n        if len(array) == 0:\n            raise ValueError(f\"Dataset {i}: input list must not be empty.\")\n        if not all(len(row) == 5 for row in array):\n            raise ValueError(f\"Dataset {i}: